"""WebSocket client session tracking protocol state."""

from frames import WSFrame
from fsm import WSState


class WSSession:
    def __init__(self, session_id: str):
        self.session_id = session_id
        self.state: str = WSState.DISCONNECTED
        self.messages_received: list[str] = []

    def handle_frame(self, frame: WSFrame) -> bool:
        if frame.opcode == "CONNECT":
            if self.state != WSState.DISCONNECTED:
                return False
            self.state = WSState.CONNECTING
            return True

        elif frame.opcode == "AUTH":
            if self.state != WSState.CONNECTING:
                return False
            if frame.auth_token == "valid_token":
                self.state = WSState.AUTHENTICATED
                return True
            return False

        elif frame.opcode == "TEXT":
            # BUG: Allows TEXT frames in CONNECTING state before authentication succeeds!
            if self.state not in (WSState.CONNECTING, WSState.AUTHENTICATED):
                return False
            self.messages_received.append(frame.payload)
            return True

        elif frame.opcode == "CLOSE":
            self.state = WSState.CLOSED
            return True

        return False

repo_files.connection_pool.py:
"""Managed pool of active WebSocket client sessions."""

from typing import Dict, Optional
from fsm import WSState
from session import WSSession


class WSPool:
    def __init__(self):
        self.sessions: Dict[str, WSSession] = {}

    def create_session(self, session_id: str) -> WSSession:
        sess = WSSession(session_id)
        self.sessions[session_id] = sess
        return sess

    def get_authenticated_count(self) -> int:
        return sum(1 for s in self.sessions.values() if s.state == WSState.AUTHENTICATED)

